mapper.select:
SELECT rt.id AS id, rt.order_no AS orderNo, rt.sales_order_id AS salesOrderId, so.order_no AS salesOrderNo, m.name AS memberName, m.phone AS memberPhone, rt.refund_amount AS refundAmount, rt.return_reason AS returnReason, rt.refund_type AS refundType, rt.cashier_name AS cashierName, rt.authorizer_name AS authorizerName, rt.return_time AS returnTime FROM return_order rt JOIN sales_order so ON so.id = rt.sales_order_id LEFT JOIN member m ON m.id = rt.member_id
AND rt.order_no LIKE CONCAT('%', #{q.orderNo}, '%')
AND so.order_no LIKE CONCAT('%', #{q.salesOrderNo}, '%')
AND (m.name LIKE CONCAT('%', #{q.memberKeyword}, '%') OR m.phone LIKE CONCAT('%', #{q.memberKeyword}, '%') OR m.member_no LIKE CONCAT('%', #{q.memberKeyword}, '%'))
AND rt.refund_type = #{q.refundType}
AND rt.return_reason = #{q.returnReason}
AND rt.cashier_name = #{q.operatorName}
AND rt.return_time >= #{q.beginDate}
AND rt.return_time < DATE_ADD(#{q.endDate}, INTERVAL 1 DAY)
ORDER BY rt.return_time DESC, rt.id DESC
